from pathlib import Path
import base64, gzip, hashlib, tarfile

SOURCE_BLOB = ''
EXPECTED_SHA256 = '5fd73afd3c5337e391958a0621e40c84d6c47e4050ff82f42c78b4a1c239193e'
source = gzip.decompress(base64.b64decode(SOURCE_BLOB))
Path("main.py").write_bytes(source)
assert hashlib.sha256(source).hexdigest() == EXPECTED_SHA256
compile(source, "main.py", "exec")
print("Agent source: PASS", len(source), "bytes", EXPECTED_SHA256)
with tarfile.open("submission.tar.gz", "w:gz") as archive:
    archive.add("main.py", arcname="main.py")
print("Submission archive: PASS", Path("submission.tar.gz").stat().st_size, "bytes")


